Lemma RI_grant_rw : forall CAPK CAPB ne bb (mo : Model) (n : Z),
  RI CAPK CAPB ne bb (m_vmmaps mo) -> CAPK <= CAPKMAX ->
  0 <= n <= NMAX ->
  vm_backing_used mo + n <= vm_limit (m_vmmaps mo) ->
  exists a, grant_ok (Z_to_bv 64 0) mo a n = true.
Proof.
