Theorem RES_free cs L BL LS cs' u nu L' BL' LS' SZ SZ' K :
  INVC x0 cs L BL LS -> RES cs SZ K -> FREL cs LS cs' u nu -> INVC x0 cs' L' BL' LS' ->
  (forall e, In e SZ' -> In e SZ) ->
  RES cs' SZ' K /\ Phi cs' = Phi cs - u /\ Psi cs' = Psi cs - Z.of_nat nu
