  creach cs L -> RES cs SZ K -> Permutation (map fst SZ) (ld_live L) ->
  Phi cs <= zsum (map (fun e => csz (snd e)) SZ) + 32 * 2 ^ 20 + PGSZ * (6 * NAMAX K + 8)
